ordersPlaced = 0;
ordersShipped = 0;
ordersDelivered = 0;
prevMonthSales = 0;
currMonthSales = 0;
prevYearSales = 0;
currYearSales = 0;

queries.tooljetdbGetOrders.data.forEach((order) => {
  ordersPlaced += order.status == "order_placed" ? 1 : 0;
  ordersShipped += order.status == "shipped" ? 1 : 0;
  ordersDelivered += order.status == "delivered" ? 1 : 0;
  prevMonthSales +=
    moment(order.order_date).format("MM|YYYY") ==
    moment().add(-1, "month").format("MM|YYYY")
      ? order.total_price
      : 0;
  currMonthSales +=
    moment(order.order_date).format("MM|YYYY") == moment().format("MM|YYYY")
      ? order.total_price
      : 0;
  prevYearSales +=
    moment(order.order_date).format("YYYY") ==
    moment().add(-1, "year").format("YYYY")
      ? order.total_price
      : 0;
  currYearSales +=
    moment(order.order_date).format("YYYY") == moment().format("YYYY")
      ? order.total_price
      : 0;
});

return {
  ordersPlaced: ordersPlaced,
  ordersShipped: ordersShipped,
  ordersDelivered: ordersDelivered,
  prevMonthSales: parseFloat(prevMonthSales.toFixed(2)),
  currMonthSales: parseFloat(currMonthSales.toFixed(2)),
  monthlySalesDiffPercentage:
    prevMonthSales > 0
      ? parseFloat(
          (((currMonthSales - prevMonthSales) / prevMonthSales) * 100).toFixed(
            2
          )
        )
      : 100,
  prevYearSales: parseFloat(prevYearSales.toFixed(2)),
  currYearSales: parseFloat(currYearSales.toFixed(2)),
  yearlySalesDiffPercentage:
    prevYearSales > 0
      ? parseFloat(
          (((currYearSales - prevYearSales) / prevYearSales) * 100).toFixed(2)
        )
      : 100,
};

queries.tooljetdbGetOrders.data;

lastThreeMonths = [
  moment().add(-2, "month").format("MMM YYYY"),
  moment().add(-1, "month").format("MMM YYYY"),
  moment().format("MMM YYYY"),
];

monthlySalesData = {
  [lastThreeMonths[0]]: 0,
  [lastThreeMonths[1]]: 0,
  [lastThreeMonths[2]]: 0,
};

queries.tooljetdbGetOrders.data.forEach((order) => {
  monthlySalesData[lastThreeMonths[0]] +=
    moment(order.order_date).format("MMM YYYY") == lastThreeMonths[0]
      ? order.total_price
      : 0;
  monthlySalesData[lastThreeMonths[1]] +=
    moment(order.order_date).format("MMM YYYY") == lastThreeMonths[1]
      ? order.total_price
      : 0;
  monthlySalesData[lastThreeMonths[2]] +=
    moment(order.order_date).format("MMM YYYY") == lastThreeMonths[2]
      ? order.total_price
      : 0;
});

chartdata = lastThreeMonths.map((monthYear) => ({
  x: monthYear,
  y: monthlySalesData[monthYear],
}));

return chartdata;
